  "steps": [
    {
      "id": 1,
      "claim": "Glaciers moving over bedrock embed debris that abrades the surface, creating linear scratches (striations).",
      "evidence": "Glacial erosion theory: basal ice carries rock fragments that act as sandpaper, producing striations on underlying bedrock (textbooks, field observations).",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "These striations are diagnostic of past glacial movement because they differ from marks made by water or wind.",
      "evidence": "Field‑geology studies show glacial striations are typically parallel, sub‑horizontal grooves with chatter marks, whereas fluvial polishing yields smooth surfaces and aeolian ventifacts have different orientations and patterns.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The presence of many scratches on rocks therefore indicates that glaciers once covered the area.",
      "evidence": "If a rock bears the specific abrasion pattern described in steps 1‑2, the most parsimonious explanation is past basal ice contact.",
      "weight": 0.20,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Fossils, moss cover, and deep burial are not uniquely linked to glaciation and can occur in many non‑glacial environments.",
      "evidence": "Fossils appear in marine, lacustrine, and terrestrial sediments; moss grows wherever moisture and shade exist; rocks become buried through sedimentation or tectonics independent of ice.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "Among the given options, only (A) – rocks have many scratches – directly matches the specific glacial indicator identified in steps 1‑3.",
      "evidence": "Steps 3 and 4 together show that scratches are a unique, observable record of glacial abrasion, whereas the other choices lack that specificity.",
      "weight": 0.15,
      "depends_on": [3, 4]
    }
  ],
  "answer": "A",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "B",
      "reason_rejected": "Fossils occur in many environments and are not a specific signature of past glaciation."
    },
    {
      "answer": "C",
      "reason_rejected": "Moss reflects current ecological conditions, not ancient glacial presence."
    },
    {
      "answer": "D",
      "reason_rejected": "Depth underground results from burial processes unrelated to surface glacial activity."
    }
